import { expect } from 'storybook/test';
import iconNames from '../../scripts/icons.json';
import { renderLiquid } from '../liquid.js';

/**
 * `snippets/ui-icon.liquid`: the theme's Lucide icons, generated by `pnpm icons:build` from `scripts/icons.json`.
 * Icons are decorative; the control around one carries its accessible name.
 */
export default {
  title: 'Elements/Icon',
  render: ({ icon, size }) => renderLiquid('ui-icon', { icon, size }),
  args: { icon: 'truck', size: 24 },
  argTypes: { icon: { control: 'select', options: iconNames }, size: { control: { type: 'number', min: 12, max: 48 } } },
};

export const Default = {
  play: async ({ canvasElement }) => {
    const svg = canvasElement.querySelector('svg.ui-icon--truck');
    await expect(svg).toHaveAttribute('width', '24');
    await expect(svg).toHaveAttribute('aria-hidden', 'true');
    await expect(svg.children.length).toBeGreaterThan(0);
  },
};

export const DefaultSize = {
  args: { size: undefined },
  play: async ({ canvasElement }) => {
    await expect(canvasElement.querySelector('svg')).toHaveAttribute('width', '16');
  },
};

export const Filled = {
  args: { icon: 'star' },
  play: async ({ canvasElement }) => {
    await expect(canvasElement.querySelector('svg')).toHaveAttribute('fill', 'currentColor');
  },
};

/** Every icon in the set, labeled with its Lucide name. */
export const All = {
  render: () =>
    `<ul style="display: grid; grid-template-columns: repeat(auto-fill, minmax(12rem, 1fr)); gap: 1.6rem; padding: 0; list-style: none">${iconNames
      .map(
        (icon) =>
          `<li style="display: flex; gap: 0.8rem; align-items: center">${renderLiquid('ui-icon', { icon, size: 20 })}<code>${icon}</code></li>`,
      )
      .join('')}</ul>`,
  play: async ({ canvas, canvasElement }) => {
    await expect(canvas.getAllByRole('listitem')).toHaveLength(iconNames.length);
    for (const svg of canvasElement.querySelectorAll('svg.ui-icon')) {
      await expect(svg.children.length).toBeGreaterThan(0);
    }
  },
};
